arguments.new_str:
# DevHelper role deployed to all ML-Platform OU accounts
dev_helper_template = {
    "Resources": {
        "DevHelperRole": {
            "Type": "AWS::IAM::Role",
            "Properties": {
                "RoleName": "DevHelper",
                "AssumeRolePolicyDocument": {
                    "Version": "2012-10-17",
                    "Statement": [
                        {
                            "Effect": "Allow",
                            "Principal": {"AWS": "*"},
                            "Action": "sts:AssumeRole",
                        }
                    ],
                },
                "ManagedPolicyArns": [
                    "arn:aws:iam::aws:policy/AdministratorAccess"
                ],
            },
        }
    }
}

CfnStackSet(
    self,
    "DevHelperRoleStackSet",
    stack_set_name="DevHelperRole",
    description="Deploys the DevHelper IAM role with AdministratorAccess to all ML-Platform OU accounts.",
    permission_model="SERVICE_MANAGED",
    auto_deployment=CfnStackSet.AutoDeploymentProperty(
        enabled=True,
        retain_stacks_on_account_removal=False,
    ),
    capabilities=["CAPABILITY_NAMED_IAM"],
    template_body=json.dumps(dev_helper_template),
    stack_instances_group=[
        CfnStackSet.StackInstancesProperty(
            deployment_targets=CfnStackSet.DeploymentTargetsProperty(
                organizational_unit_ids=[org_units.ous["ML-Platform"].ref],
            ),
            regions=[self.region],
        )
    ],
)

# SCP Monitoring for security alerting
SCPMonitoring(self)

